parameters.functionCode:
const pgResult = $node['Check PostgreSQL'].json;
const redisResult = $node['Check Redis'].json;
const n8nResult = $node['Check n8n API'].json;

const checks = [];
let overallStatus = 'healthy';

// PostgreSQL check
const pgHealthy = pgResult?.healthy === 1;
checks.push({
  component: 'postgres',
  status: pgHealthy ? 'healthy' : 'down',
  details: pgHealthy ? {
    db_size_mb: Math.round((pgResult.db_size_bytes || 0) / 1024 / 1024),
    active_connections: pgResult.active_connections || 0,
    total_connections: pgResult.total_connections || 0
  } : { error: 'Connection failed' }
});
if (!pgHealthy) overallStatus = 'down';

// Redis check
const redisHealthy = !redisResult?.error;
checks.push({
  component: 'redis',
  status: redisHealthy ? 'healthy' : 'degraded',
  details: redisHealthy ? { connected: true } : { error: 'Connection failed' }
});
if (!redisHealthy && overallStatus === 'healthy') overallStatus = 'degraded';

// n8n check
const n8nHealthy = n8nResult?.status === 'ok' || n8nResult?.statusCode === 200 || !n8nResult?.error;
checks.push({
  component: 'n8n',
  status: n8nHealthy ? 'healthy' : 'down',
  details: n8nHealthy ? { responsive: true } : { error: 'API not responding' }
});
if (!n8nHealthy) overallStatus = 'down';

// Disk/memory estimates
const memUsage = process.memoryUsage();
checks.push({
  component: 'n8n_memory',
  status: memUsage.heapUsed / memUsage.heapTotal > 0.9 ? 'degraded' : 'healthy',
  details: {
    heap_used_mb: Math.round(memUsage.heapUsed / 1024 / 1024),
    heap_total_mb: Math.round(memUsage.heapTotal / 1024 / 1024),
    usage_percent: Math.round(memUsage.heapUsed / memUsage.heapTotal * 100)
  }
});

return [{
  json: {
    overall_status: overallStatus,
    checks: checks,
    checked_at: new Date().toISOString(),
    has_critical: overallStatus === 'down'
  }
}];

parameters.text:
🚨 *SYSTEM HEALTH CRITICAL*

*Overall Status:* {{ $json.overall_status }}
*Time:* {{ $json.checked_at }}

*Component Status:*
{{ $json.checks.map(c => `• *${c.component}*: ${c.status === 'healthy' ? '✅' : c.status === 'degraded' ? '⚠️' : '❌'} ${c.status}`).join('\n') }}

*Details:*
{{ $json.checks.filter(c => c.status !== 'healthy').map(c => `• ${c.component}: ${JSON.stringify(c.details)}`).join('\n') }}

⚡ Immediate investigation required!
